<?php require_once __DIR__.'/../config.php'; $u=require_admin(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check(); $action=$_POST['action']??''; if($action==='add'){ $stmt=$pdo->prepare('INSERT INTO users(name,email,password,role) VALUES(?,?,?,\'driver\')'); try{$stmt->execute([trim($_POST['name']),trim($_POST['email']),password_hash($_POST['password'],PASSWORD_DEFAULT)]);flash('Motorista criado.');}catch(Exception $e){flash('Não foi possível criar: email já utilizado.');} } elseif($action==='toggle'){ $stmt=$pdo->prepare('UPDATE users SET active=CASE active WHEN 1 THEN 0 ELSE 1 END WHERE id=? AND role=\'driver\''); $stmt->execute([(int)$_POST['id']]); flash('Estado do motorista atualizado.'); } redirect('drivers.php');}
$rows=$pdo->query("SELECT * FROM users WHERE role='driver' ORDER BY name")->fetchAll(); layout_start('Motoristas',$u); ?>
<div class="page-head"><div><h1>Motoristas</h1><p class="muted">Apenas administradores podem adicionar ou desativar motoristas.</p></div></div>
<div class="two-col"><section class="card"><h2>Novo motorista</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><label>Nome<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Palavra-passe inicial<input type="password" name="password" required minlength="8"></label><button class="btn primary">Adicionar motorista</button></form></section><section class="card"><h2>Motoristas</h2><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Email</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><span class="pill <?= $r['active']?'on':'off'?>"><?= $r['active']?'Ativo':'Desativado'?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="linkbtn"><?= $r['active']?'Desativar':'Ativar'?></button></form></td></tr><?php endforeach; ?></tbody></table></div></section></div>
<?php layout_end(); ?>
